DEFAULT_MAX_RELOAD_WORK = 10000000
DEFAULT_MAX_RECORD_WORK = 10000000
DEFAULT_MAX_REPLAY_WORK = 10000000
DEFAULT_MAX_DIFF_WORK = 10000000
DEFAULT_MAX_LINK_WORK = 10000000
# config-export 三项上限的默认值沿用 config-diff（工作量/输入/输出）
DEFAULT_MAX_EXPORT_WORK = DEFAULT_MAX_DIFF_WORK
# config-import 三项上限默认值：工作量沿用 config-export，输入/输出各 1 MiB
DEFAULT_MAX_IMPORT_WORK = DEFAULT_MAX_EXPORT_WORK
CONFIG_IMPORT_MAX_INPUT_BYTES = 1024 * 1024
CONFIG_IMPORT_MAX_OUTPUT_BYTES = 1024 * 1024
_LIMIT_RE = re.compile(r"[1-9][0-9]*")
_READ_CHUNK = 65536


def _limit_value(token):
    """十进制上限串转整数：逐位累加，任意长度按数学整数处理。"""
    value = 0
    for char in token:
        value = value * 10 + ord(char) - ord("0")
    return value


def _parse_limits(tokens, counts, defaults):
    """解析可选上限（个数须属于 counts，均须匹配 [1-9][0-9]*）。

    返回解析值加 defaults 中缺省项；个数不对或任一参数非法返回 None
    （调用方按 usage 处理）。
    """
    if len(tokens) not in counts:
        return None
    if any(_LIMIT_RE.fullmatch(token) is None for token in tokens):
        return None
    parsed = tuple(_limit_value(token) for token in tokens)
    return parsed + defaults[len(parsed):]


def _read_limited(handle, limit):
    """按至多 65536 字节分块读取；超过 limit 即停止并返回 None。

    额度未尽时单次至多请求剩余量，耗尽后只读 1 字节探测超限。
    """
    chunks = []
    total = 0
    while True:
        remaining = limit - total
        if remaining > 0:
            chunk = handle.read(min(_READ_CHUNK, remaining))
        else:
            chunk = handle.read(1)
        if not chunk:
            return b"".join(chunks)
        chunks.append(chunk)
        total += len(chunk)
        if total > limit:
            return None


RECORD_SCHEMA = 1
LOG_KEYS = ("schema", "config", "records", "sha256")
RECORD_KEYS = ("t", "version", "event", "applied", "output")
EVENT_KIND_BY_KEYS = {
    STP_EVENT_KEYS: "link",
    MEMBER_EVENT_KEYS: "member",
    SERVICE_EVENT_KEYS: "service",
    FRAME_KEYS_ACL: "frame",
    RELOAD_EVENT_KEYS: "reload",
    ROLLBACK_EVENT_KEYS: "rollback",
}
_HEX64_RE = re.compile(r"[0-9a-f]{64}\Z")


def _event_kind(event):
    if not isinstance(event, dict):
        raise InvalidInput("bad log event")
    kind = EVENT_KIND_BY_KEYS.get(frozenset(event))
    if kind is None:
        raise InvalidInput("bad log event")
    return kind


def _run_reload(config, events, observe, max_work=None):
    """reload/record/replay 共用：校验配置与事件并执行 port-security 仿真。

    事件允许 {t, rollback} 回滚事件（语义同 reload-rollback 子命令）。
    返回 (reload 结果 dict, observer 或 None)。全部校验与非法重载检测先于返回。
    max_work 非 None 时（record），全量语义校验后先按 reload 公式无副作用
    预演；首次超过即抛 ReloadWorkLimit，不正式仿真。
    """
    (
        bridges,
        links,
        delay,
        bridge,
        ports,
        age,
        storm,
        lags,
        mirror,
        acl,
        qos,
        security,
    ) = validate_security_config(config)
    link_ids = {link["id"] for link in links}
    reload_events, final_config = validate_reload_events(
        events, ports, link_ids, lags, config, allow_rollback=True
    )
    if max_work is not None:
        # 与 reload 入口同一公式：独立链路副本与空状态，不改动既有数据
        reload_work(
            bridges,
            links,
            delay,
            bridge,
            ports,
            age,
            storm,
            lags,
            acl,
            qos,
            security,
            reload_events,
            max_work,
        )
    observer = {} if observe else None
    result = forward_security(
        bridges,
        links,
        delay,
        bridge,
        ports,
        age,
        storm,
        lags,
        mirror,
        acl,
        qos,
        security,
        reload_events,
        observer=observer,
    )
    result["config"] = _canonical(final_config)
    return result, observer


def _build_log_doc(config, events, items):
    """构造 LOG 文档（含 sha256）；records 与事件等长、同序。"""
    if len(events) != len(items):
        raise InvalidInput("bad log")
    records = []
    version = 0  # version 初值 0，取事件后值；每次 reload/rollback（无变化亦算）加 1
    for event, observed in zip(events, items):
        kind = _event_kind(event)
        if kind != observed["kind"]:
            raise InvalidInput("bad log")
        if kind in ("reload", "rollback"):
            version += 1
        records.append(
            {
                "t": event["t"],
                "version": version,
                "event": _canonical(event),
                "applied": observed["applied"],
                "output": observed["output"],
            }
        )
    doc = {
        "schema": RECORD_SCHEMA,
        "config": _canonical(config),
        "records": records,
    }
    doc["sha256"] = hashlib.sha256(_log_prefix_bytes(doc)).hexdigest()
    return doc


def _log_prefix_bytes(doc):
    """sha256 摘要文本：schema,config,records 规范序列化后含 LF。"""
    prefix = {
        "schema": doc["schema"],
        "config": doc["config"],
        "records": doc["records"],
    }
    return (
        json.dumps(prefix, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _log_bytes(doc):
    ordered = {key: doc[key] for key in LOG_KEYS}
    return (
        json.dumps(ordered, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _assert_canonical_order(value):
    """config/event 内对象键须递归按 Unicode 码点升序，数组保序。"""
    if isinstance(value, dict):
        keys = list(value)
        if keys != sorted(keys):
            raise InvalidInput("bad log key order")
        for item in value.values():
            _assert_canonical_order(item)
    elif isinstance(value, list):
        for item in value:
            _assert_canonical_order(item)


def _json_equal(a, b):
    """JSON 值深比较；bool 不与 int 混同，键序无关，数组保序。"""
    if isinstance(a, bool) or isinstance(b, bool):
        return isinstance(a, bool) and isinstance(b, bool) and a == b
    if isinstance(a, dict) and isinstance(b, dict):
        return a.keys() == b.keys() and all(
            _json_equal(a[key], b[key]) for key in a
        )
    if isinstance(a, list) and isinstance(b, list):
        return len(a) == len(b) and all(
            _json_equal(x, y) for x, y in zip(a, b)
        )
    if a is None or b is None:
        return a is None and b is None
    return type(a) is type(b) and a == b


def _validate_log_shape(log):
    """严格校验 LOG 字段、类型、键序；不含语义重放。"""
    if not isinstance(log, dict) or list(log) != list(LOG_KEYS):
        raise InvalidInput("bad log")
    if not _is_int(log["schema"]) or log["schema"] != RECORD_SCHEMA:
        raise InvalidInput("bad log schema")
    config = log["config"]
    if not isinstance(config, dict):
        raise InvalidInput("bad log config")
    _assert_canonical_order(config)
    records = log["records"]
    if not isinstance(records, list):
        raise InvalidInput("bad log records")
    for record in records:
        if not isinstance(record, dict) or list(record) != list(RECORD_KEYS):
            raise InvalidInput("bad log record")
        if not _is_int(record["t"]) or record["t"] < 0:
            raise InvalidInput("bad log t")
        if not _is_int(record["version"]) or record["version"] < 0:
            raise InvalidInput("bad log version")
        event = record["event"]
        if not isinstance(event, dict):
            raise InvalidInput("bad log event")
        _assert_canonical_order(event)
        _event_kind(event)
        if not isinstance(record["applied"], bool):
            raise InvalidInput("bad log applied")
        if record["output"] is not None and not isinstance(
            record["output"], dict
        ):
            raise InvalidInput("bad log output")
    digest = log["sha256"]
    if not isinstance(digest, str) or _HEX64_RE.fullmatch(digest) is None:
        raise InvalidInput("bad log sha256")


def _verify_records(log, events, items):
    """重放后逐项核对 t/version/event/applied/output。"""
    records = log["records"]
    if len(records) != len(items):
        raise InvalidInput("bad log records")
    version = 0
    for event, observed, record in zip(events, items, records):
        kind = _event_kind(event)
        if kind != observed["kind"]:
            raise InvalidInput("bad log record")
        if kind in ("reload", "rollback"):
            version += 1
        if record["t"] != event["t"]:
            raise InvalidInput("bad log t")
        if record["version"] != version:
            raise InvalidInput("bad log version")
        if not _json_equal(record["event"], _canonical(event)):
            raise InvalidInput("bad log event")
        if record["applied"] is not observed["applied"]:
            raise InvalidInput("bad log applied")
        if not _json_equal(record["output"], observed["output"]):
            raise InvalidInput("bad log output")


def _atomic_write(path, payload):
    """同目录临时文件 + os.replace 原子写入；失败不改动目标。"""
    directory = os.path.dirname(os.path.abspath(path))
    fd, tmp_path = tempfile.mkstemp(prefix=".switch-log-", dir=directory)
    try:
        with os.fdopen(fd, "wb") as handle:
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(tmp_path, path)
    except OSError:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise


def _result_bytes(result):
    """stdout 载荷：紧凑 UTF-8 JSON 加一个 LF。"""
    return (
        json.dumps(result, ensure_ascii=False, separators=(",", ":")).encode(
            "utf-8"
        )
        + b"\n"
    )


def _cmd_record(
    config_path,
    events_path,
    log_path,
    max_events,
    max_log_bytes,
    max_config_bytes,
    max_events_bytes,
    max_output_bytes,
    max_record_work,
):
    try:
        with open(config_path, "rb") as config_handle, open(
            events_path, "rb"
        ) as events_handle:
            # 两文件均可读后，先判 CONFIG 原始字节，再判 EVENTS 原始字节
            config_raw = _read_limited(config_handle, max_config_bytes)
            if config_raw is None:
                _fail("config_limit")
                return 5
            events_raw = _read_limited(events_handle, max_events_bytes)
            if events_raw is None:
                _fail("events_limit")
                return 5
    except OSError:
        _fail("file_not_found")
        return 3
    try:
        # 事件上界先于解析与预演判定；超限时绝不触碰 LOG
        events_preview = parse_json(events_raw)
        if isinstance(events_preview, list) and len(events_preview) > max_events:
            _fail("event_limit")
            return 5
        # 先无副作用预演：解析、全部校验与各重载点检测均在内存完成；
        # 工作量预演在语义校验后、正式仿真与 LOG 构造前，超限绝不触碰 LOG
        config = parse_json(config_raw)
        events = events_preview
        result, observer = _run_reload(config, events, True, max_record_work)
        doc = _build_log_doc(config, events, observer["items"])
        payload = _log_bytes(doc)
        # 字节上界（含末尾 LF）在写入前判定；等于上限合法
        if len(payload) > max_log_bytes:
            _fail("log_limit")
            return 5
        # 输出上界在 log_limit 之后、原子写 LOG 之前判定；超限时绝不触碰 LOG
        output = _result_bytes(result)
        if len(output) > max_output_bytes:
            _fail("output_limit")
            return 5
        _atomic_write(log_path, payload)  # 成功后才原子写 LOG
    except InvalidInput:
        _fail("invalid_input")
        return 4
    except ReloadWorkLimit:
        _fail("record_work_limit")
        return 5
    except OSError:
        _fail("file_not_found")
        return 3
    sys.stdout.buffer.write(output)
    return 0


def _cmd_replay(
    log_path, max_events, max_log_bytes, max_output_bytes, max_replay_work
):
    try:
        with open(log_path, "rb") as handle:
            log_raw = _read_limited(handle, max_log_bytes)
    except OSError:
        _fail("file_not_found")
        return 3
    # 字节上界先判定（分块读取、超限即停，含末尾 LF）
    if log_raw is None:
        _fail("log_limit")
        return 5
    try:
        log = parse_json(log_raw)  # 全量校验先于重放
        _validate_log_shape(log)
        if hashlib.sha256(_log_prefix_bytes(log)).hexdigest() != log["sha256"]:
            raise InvalidInput("bad log sha256")
        config = log["config"]
        events = [record["event"] for record in log["records"]]
        # records 上界在解析校验后、重放前判定
        if len(log["records"]) > max_events:
            _fail("event_limit")
            return 5
        # 状态语义校验后先按 record 同一公式无副作用预演；首次超限即停止，

def validate_reload_events(events, ports, link_ids, lags, config,
                           allow_rollback=False):
    """reload 子命令事件：普通事件沿用 qos，另含 {t, config} 重载事件。

    返回 (事件序列, 末态原始配置)；重载事件的 config 须为完整有效配置，
    且仅 age/acl/security 可与当时配置不同。全部校验先于执行。
    allow_rollback 时另含 {t, rollback} 事件（rollback 只能为 true）：
    reload 前压入当前配置，rollback 弹栈恢复，空栈为 invalid_input。
    """
    if not isinstance(events, list):
        raise InvalidInput("events must be a list")
    names = {port["name"] for port in ports}
    member_set = {member for lag in lags for member in lag["members"]}
    result = []
    prev_t = None
    current = config
    stack = []  # reload 前压入的原始配置；rollback 弹栈恢复
    for event in events:
        if not isinstance(event, dict):
            raise InvalidInput("bad event")
        keys = frozenset(event)
        if keys == STP_EVENT_KEYS:
            t = event["t"]
            lid = event["id"]
            up = event["up"]
            if not _is_int(t) or t < 0:
                raise InvalidInput("bad t")
            if prev_t is not None and t < prev_t:
                raise InvalidInput("t not monotonic")
            if not isinstance(lid, str) or not lid or lid not in link_ids:
                raise InvalidInput("bad event id")
            if not isinstance(up, bool):
                raise InvalidInput("bad up")
            result.append(("link", t, lid, up))
        elif keys == MEMBER_EVENT_KEYS:
            t = event["t"]
            member = event["member"]
            up = event["up"]
            if not _is_int(t) or t < 0:
                raise InvalidInput("bad t")
            if prev_t is not None and t < prev_t:
                raise InvalidInput("t not monotonic")
            if not isinstance(member, str) or member not in member_set:
                raise InvalidInput("bad event member")
            if not isinstance(up, bool):
                raise InvalidInput("bad up")
            result.append(("member", t, member, up))
        elif keys == SERVICE_EVENT_KEYS:
            t = event["t"]
            port = event["port"]
            count = event["count"]
            if not _is_int(t) or t < 0:
                raise InvalidInput("bad t")
            if prev_t is not None and t < prev_t:
                raise InvalidInput("t not monotonic")
            if not isinstance(port, str) or port not in names:
                raise InvalidInput("unknown port")
            if not _is_int(count) or count <= 0:
                raise InvalidInput("bad count")
            result.append(("service", t, port, count))
        elif keys == FRAME_KEYS_ACL:
            t = event["t"]
            port = event["port"]
            src = event["src"]
            dst = event["dst"]
            vlan = event["vlan"]
            ethertype = event["ethertype"]
            priority = event["priority"]
            if not _is_int(t) or t < 0:
                raise InvalidInput("bad t")
            if prev_t is not None and t < prev_t:
                raise InvalidInput("t not monotonic")
            if not isinstance(port, str) or port not in names:
                raise InvalidInput("unknown port")
            if not valid_mac(src):
                raise InvalidInput("bad src")
            if not valid_dst_mac(dst):
                raise InvalidInput("bad dst")
            if vlan is not None and not _valid_vlan_id(vlan):
                raise InvalidInput("bad vlan")
            if not _is_int(ethertype) or not 0 <= ethertype <= 65535:
                raise InvalidInput("bad ethertype")
            if not _is_int(priority) or not 0 <= priority <= 7:
                raise InvalidInput("bad priority")
            result.append(
                ("frame", t, port, src, dst, vlan, ethertype, priority)
            )
        elif keys == RELOAD_EVENT_KEYS:
            t = event["t"]
            new_config = event["config"]
            if not _is_int(t) or t < 0:
                raise InvalidInput("bad t")
            if prev_t is not None and t < prev_t:
                raise InvalidInput("t not monotonic")
            if not isinstance(new_config, dict):
                raise InvalidInput("bad reload config")
            (
                _bridges,
                _links,
                _delay,
                _bridge,
                _ports,
                new_age,
                _storm,
                _lags,
                _mirror,
                new_acl,
                _qos,
                new_security,
            ) = validate_security_config(new_config)
            for key in current:
                if (
                    key not in RELOAD_MUTABLE_KEYS
                    and new_config[key] != current[key]
                ):
                    raise InvalidInput("reload may only change age/acl/security")
            changes = []
            for key in RELOAD_MUTABLE_KEYS:
                if new_config[key] != current[key]:
                    changes.append(
                        {
                            "key": key,
                            "before": _canonical(current[key]),
                            "after": _canonical(new_config[key]),
                        }
                    )
            if allow_rollback:
                stack.append(current)  # reload 前压入当前配置
            current = new_config
            result.append(
                ("reload", t, new_age, new_acl, new_security, changes)
            )
        elif allow_rollback and keys == ROLLBACK_EVENT_KEYS:
            t = event["t"]
            if not _is_int(t) or t < 0:
                raise InvalidInput("bad t")
            if prev_t is not None and t < prev_t:
                raise InvalidInput("t not monotonic")
            if event["rollback"] is not True:
                raise InvalidInput("bad rollback")
            if not stack:
                raise InvalidInput("rollback stack empty")
            new_config = stack.pop()
            (
                _bridges,
                _links,
                _delay,
                _bridge,
                _ports,
                new_age,
                _storm,
                _lags,
                _mirror,
                new_acl,
                _qos,
                new_security,
            ) = validate_security_config(new_config)
            changes = []
            for key in RELOAD_MUTABLE_KEYS:
                if new_config[key] != current[key]:
                    changes.append(
                        {
                            "key": key,
                            "before": _canonical(current[key]),
                            "after": _canonical(new_config[key]),
                        }
                    )
            current = new_config
            result.append(
                ("rollback", t, new_age, new_acl, new_security, changes)
            )
        else:
            raise InvalidInput("bad event")
        prev_t = t
    return result, current


def forward_lag(
    bridges, links, delay, bridge_name, ports, age, storm, lags, events
):
    window = storm["window"]
    limits = storm["limits"]
    move_limit = storm["move_limit"]
    hold = storm["hold"]
    by_id = {link["id"]: link for link in links}
    by_name = {port["name"]: port for port in ports}
    lag_by_name = {lag["name"]: lag for lag in lags}
    lag_of = {}  # 成员物理口 -> lag
    member_up = {}  # 成员物理口 -> 动态可用（初始可用）
    for lag in lags:
        for member in lag["members"]:
            lag_of[member] = lag
            member_up[member] = True
    port_link = {}  # 本桥桥链路口名 -> link
    for link in links:
        for end_bridge, end_port in (link["x"], link["y"]):
            if end_bridge == bridge_name:
                port_link[end_port] = link
    fdb = {}  # (vlan, mac) -> [逻辑口（物理口名或 lag 名）, seen]
    port_stats = {
        port["name"]: {"rx": 0, "tx": 0, "drop": 0} for port in ports
    }
    vlan_stats = {}
    for port in ports:
        for vlan in port["allowed"]:
            vlan_stats.setdefault(vlan, {"rx": 0, "tx": 0, "drop": 0})
    rate_queues = {}  # (入端口, vlan, 类别) -> 放行时刻 deque
    move_queues = {}  # (vlan, src) -> 迁移时刻 deque
    last_learn = {}  # (vlan, src) -> 最后学习逻辑口
    blocked = {}  # (入端口, vlan) -> 封锁截止时刻
    results = []

    previous = {}  # (bridge, port) -> 上一轮角色
    since = {}  # (bridge, port) -> 获得当前 root/designated 角色的时刻
    roles = {name: {} for name in bridges}

    def converge(t):
        _, _, new_roles = stp_converge(bridges, links)
        for name in bridges:
            for port, role in new_roles[name].items():
                key = (name, port)
                if role in STP_TIMED_ROLES:
                    if previous.get(key) != role:  # 同角色不重计时
                        since[key] = t
                else:
                    since.pop(key, None)
        previous.clear()
        for name in bridges:
            for port, role in new_roles[name].items():
                previous[(name, port)] = role
        roles.clear()
        for name in bridges:
            roles[name] = new_roles[name]

    def forwarding_ports(t):
        result = set()
        for name, link in port_link.items():
            key = (bridge_name, name)
            role = roles[bridge_name][name]
            if (
                by_name[name]["up"]
                and link["up"]
                and role in STP_TIMED_ROLES
                and t - since[key] >= 2 * delay
            ):
                result.add(name)
        return result

    def port_status(name, t):
        """返回 (物理 up, STP 状态)；边缘口恒为 up 即 forwarding。"""
        port = by_name[name]
        link = port_link.get(name)
        if link is None:
            return port["up"], ("forwarding" if port["up"] else "down")
        if not port["up"]:
            return False, "down"
        if not link["up"]:
            return False, "disabled"
        role = roles[bridge_name][name]
        if role in STP_TIMED_ROLES:
            elapsed = t - since[(bridge_name, name)]
            if elapsed < delay:
                state = "discarding"
            elif elapsed < 2 * delay:
                state = "learning"
            else:
                state = "forwarding"
        else:
            state = "discarding"  # alternate
        return True, state

    def member_available(name, t, vlan):
        """成员可用：动态 up、端口 up、STP forwarding 且允许该 VLAN。"""
        port = by_name[name]
        if not member_up[name] or not port["up"] or vlan not in port["allowed"]:
            return False
        return port_status(name, t) == (True, "forwarding")

    def lag_candidates(lag, t, vlan):
        """可用候选成员，按 members 顺序。"""
        return [
            member
            for member in lag["members"]
            if member_available(member, t, vlan)
        ]

    def lag_pick(lag, candidates, src, dst, vlan):
        parts = []
        for field in lag["hash"]:
            if field == "src":
                parts.append(src)
            elif field == "dst":
                parts.append(dst)
            else:
                parts.append(str(vlan))
        digest = zlib.crc32("|".join(parts).encode("utf-8")) & 0xFFFFFFFF
        return candidates[digest % len(candidates)]

    def suppress(t, port_name, vlan, src, dst, state, learn_port):
        """风暴控制：返回 True 表示本帧被抑制（不学习、不发送）。"""

def forward_qos(
    bridges, links, delay, bridge_name, ports, age, storm, lags, mirror,
    acl, qos, events
):
    window = storm["window"]
    limits = storm["limits"]
    move_limit = storm["move_limit"]
    hold = storm["hold"]
    sources = mirror["sources"]
    mirror_target = mirror["target"]
    direction = mirror["direction"]
    source_set = set(sources)
    qos_map = qos["map"]
    cap = qos["cap"]
    sched_mode = qos["mode"]
    weights = qos["weights"]
    drop_mode = qos["drop"]
    weight_total = sum(weights)
    quotas = [-(-(cap * w) // weight_total) for w in weights]  # 上取整
    by_id = {link["id"]: link for link in links}
    by_name = {port["name"]: port for port in ports}
    lag_by_name = {lag["name"]: lag for lag in lags}
    lag_of = {}  # 成员物理口 -> lag
    member_up = {}  # 成员物理口 -> 动态可用（初始可用）
    for lag in lags:
        for member in lag["members"]:
            lag_of[member] = lag
            member_up[member] = True
    port_link = {}  # 本桥桥链路口名 -> link
    for link in links:
        for end_bridge, end_port in (link["x"], link["y"]):
            if end_bridge == bridge_name:
                port_link[end_port] = link
    fdb = {}  # (vlan, mac) -> [逻辑口（物理口名或 lag 名）, seen]
    port_stats = {
        port["name"]: {"rx": 0, "tx": 0, "drop": 0} for port in ports
    }
    vlan_stats = {}
    for port in ports:
        for vlan in port["allowed"]:
            vlan_stats.setdefault(vlan, {"rx": 0, "tx": 0, "drop": 0})
    rate_queues = {}  # (入端口, vlan, 类别) -> 放行时刻 deque
    move_queues = {}  # (vlan, src) -> 迁移时刻 deque
    last_learn = {}  # (vlan, src) -> 最后学习逻辑口
    blocked = {}  # (入端口, vlan) -> 封锁截止时刻
    results = []
    # 出口队列：每端口 4 个优先级 FIFO，存 {"id","vlan","mirror"}
    egress_queues = {
        port["name"]: [deque(), deque(), deque(), deque()] for port in ports
    }
    # 每物理出口持久 WRR 状态 (当前队, 剩余配额)；初始服务 3 队
    wrr_state = {
        port["name"]: [3, weights[3]] for port in ports
    }
    frame_seq = 0  # 全局零基帧序号（仅帧事件占用）

    def converge(t):
        _, _, new_roles = stp_converge(bridges, links)
        for name in bridges:
            for port, role in new_roles[name].items():
                key = (name, port)
                if role in STP_TIMED_ROLES:
                    if previous.get(key) != role:  # 同角色不重计时
                        since[key] = t
                else:
                    since.pop(key, None)
        previous.clear()
        for name in bridges:
            for port, role in new_roles[name].items():
                previous[(name, port)] = role
        roles.clear()
        for name in bridges:
            roles[name] = new_roles[name]

    def forwarding_ports(t):
        result = set()
        for name, link in port_link.items():
            key = (bridge_name, name)
            role = roles[bridge_name][name]
            if (
                by_name[name]["up"]
                and link["up"]
                and role in STP_TIMED_ROLES
                and t - since[key] >= 2 * delay
            ):
                result.add(name)
        return result

    def port_status(name, t):
        """返回 (物理 up, STP 状态)；边缘口恒为 up 即 forwarding。"""
        port = by_name[name]
        link = port_link.get(name)
        if link is None:
            return port["up"], ("forwarding" if port["up"] else "down")
        if not port["up"]:
            return False, "down"
        if not link["up"]:
            return False, "disabled"
        role = roles[bridge_name][name]
        if role in STP_TIMED_ROLES:
            elapsed = t - since[(bridge_name, name)]
            if elapsed < delay:
                state = "discarding"
            elif elapsed < 2 * delay:
                state = "learning"
            else:
                state = "forwarding"
        else:
            state = "discarding"  # alternate
        return True, state

    def is_forwarding(name, t):
        """LAG 成员还需动态 up 才算 forwarding。"""
        phys_up, state = port_status(name, t)
        if not phys_up or state != "forwarding":
            return False
        return name not in member_up or member_up[name]

    def member_available(name, t, vlan):
        """成员可用：动态 up、端口 up、STP forwarding 且允许该 VLAN。"""
        port = by_name[name]
        if not member_up[name] or not port["up"] or vlan not in port["allowed"]:
            return False
        return port_status(name, t) == (True, "forwarding")

    def lag_candidates(lag, t, vlan):
        """可用候选成员，按 members 顺序。"""
        return [
            member
            for member in lag["members"]
            if member_available(member, t, vlan)
        ]

    def lag_pick(lag, candidates, src, dst, vlan):
        parts = []
        for field in lag["hash"]:
            if field == "src":
                parts.append(src)
            elif field == "dst":
                parts.append(dst)
            else:
                parts.append(str(vlan))
        digest = zlib.crc32("|".join(parts).encode("utf-8")) & 0xFFFFFFFF
        return candidates[digest % len(candidates)]

    def suppress(t, port_name, vlan, src, dst, state, learn_port):
        """风暴控制：返回 True 表示本帧被抑制（不学习、不发送）。"""
        if (port_name, vlan) in blocked:  # 封锁帧不检测
            return True
        if state not in ("learning", "forwarding"):
            return False
        is_group = int(dst[:2], 16) & 1
        if dst == BROADCAST_MAC:
            category = "broadcast"
        elif is_group:
            category = "multicast"
        else:
            category = None if fdb.get((vlan, dst)) else "unknown"
        if category is not None:
            queue = rate_queues.get((port_name, vlan, category))
            if queue is None:
                queue = deque(maxlen=limits[category])
                rate_queues[(port_name, vlan, category)] = queue
            while queue and t - queue[0] >= window:
                queue.popleft()
            if len(queue) >= limits[category]:  # 余量已达上限：丢弃
                return True
        prev = last_learn.get((vlan, src))
        if prev is not None and prev != learn_port:  # 学习端口迁移
            queue = move_queues.get((vlan, src))
            if queue is None:
                queue = deque(maxlen=move_limit)
                move_queues[(vlan, src)] = queue
            while queue and t - queue[0] >= window:
                queue.popleft()
            queue.append(t)
            if len(queue) >= move_limit:  # 迁移数达上限：封锁入端口/VLAN 并丢弃
                blocked[(port_name, vlan)] = t + hold
                return True
        if category is not None:  # 速率名额仅在帧实际放行时占用
            rate_queues[(port_name, vlan, category)].append(t)
        fdb[(vlan, src)] = [learn_port, t]
        last_learn[(vlan, src)] = learn_port
        return False

    def target_available(t):
        """镜像输出口须物理 up；其本桥链路（若有）也须 up。STP 不阻止镜像。"""
        port = by_name[mirror_target]
        if not port["up"]:
            return False
        link = port_link.get(mirror_target)
        if link is not None and not link["up"]:
            return False
        return True

    def mirror_entry(direction_name, tag, source, t):
        """构造镜像副本；tag 为源侧线路上实际携带的标签（可为 None）。"""
        if not target_available(t):  # 不可用则无副本
            return None
        port_stats[mirror_target]["tx"] += 1  # 副本只计 target 的 tx

        return {
            "name": mirror_target,
            "vlan": tag,
            "direction": direction_name,
            "source": source,
        }

    def acl_match(vlan, src, dst, ethertype, priority):
        """按数组序首条命中；未命中视为 allow。"""
        for rule in acl:
            if (
                (rule["src"] is None or rule["src"] == src)
                and (rule["dst"] is None or rule["dst"] == dst)
                and (rule["vlan"] is None or rule["vlan"] == vlan)
                and (
                    rule["ethertype"] is None
                    or rule["ethertype"] == ethertype
                )
                and (
                    rule["priority"] is None or rule["priority"] == priority
                )
            ):
                return rule["action"], rule["to_vlan"]
        return "allow", None

    def clear_queue(name):
        """非 forwarding 清队：逐帧计出口与 VLAN drop。"""
        for q in range(4):
            while egress_queues[name][q]:
                frame = egress_queues[name][q].popleft()
                port_stats[name]["drop"] += 1
                vlan_stats[frame["vlan"]]["drop"] += 1

    def admit(name, queue_idx):
        """tail：总数达 cap 即拒；weighted：任一队列配额满即拒。"""
        queues = egress_queues[name]
        if drop_mode == "tail":
            return sum(len(q) for q in queues) < cap
        return all(len(queues[q]) < quotas[q] for q in range(4))

    previous = {}  # (bridge, port) -> 上一轮角色
    since = {}  # (bridge, port) -> 获得当前 root/designated 角色的时刻
    roles = {name: {} for name in bridges}

    converge(0)
    for item in events:
        t = item[1]
        for key in [k for k, (_, seen) in fdb.items() if t - seen >= age]:
            del fdb[key]
        for key in [k for k, until in blocked.items() if t >= until]:
            del blocked[key]
        if item[0] == "link":
            _, t, lid, up = item
            if by_id[lid]["up"] != up:  # 幂等链路事件不重算拓扑
                old_forwarding = forwarding_ports(t)
                by_id[lid]["up"] = up
                converge(t)
                for name in old_forwarding - forwarding_ports(t):
                    for key in [k for k, (p, _) in fdb.items() if p == name]:
                        del fdb[key]
                    clear_queue(name)  # 离开 forwarding：清队
            continue
        if item[0] == "member":
            _, t, member, up = item
            member_up[member] = up  # 幂等无作用；可用性变化不清 FDB
            if not up:  # 成员下线即非 forwarding：清队
                clear_queue(member)
            continue
        if item[0] == "service":
            _, t, port_name, count = item
            frames = []
            mirrors = []
            if not is_forwarding(port_name, t):  # 非 forwarding：清队不服务
                clear_queue(port_name)
            else:
                queues = egress_queues[port_name]
                served = 0

                def dequeue_one():
                    frame = queues[q].popleft()
                    port_stats[port_name]["tx"] += 1  # tx 仅服务时计
                    vlan_stats[frame["vlan"]]["tx"] += 1
                    frames.append(frame["id"])
                    # 仅实际产生出站副本才追加（无 null 占位），与发送帧同序
                    if (
                        direction in ("egress", "both")
                        and port_name in source_set
                    ):
                        copy = mirror_entry(
                            "egress", frame["mirror"], port_name, t
                        )
                        if copy is not None:
                            mirrors.append(copy)

                while served < count:
                    if sched_mode == "sp":
                        q = next(
                            (q for q in (3, 2, 1, 0) if queues[q]), None
                        )
                        if q is None:
                            break
                        dequeue_one()
                        served += 1
                    else:  # wrr：持久状态 (q, rem)
                        q, rem = wrr_state[port_name]
                        if not any(queues):  # 四队全空：停止且状态不变
                            break
                        while not queues[q]:  # 当前队空：推进并重置配额
                            q = (q - 1) % 4
                            rem = weights[q]
                        dequeue_one()
                        served += 1
                        rem -= 1  # 每发一帧 rem 减 1
                        if rem == 0 or not queues[q]:
                            # rem 用尽或当前队变空：推进并重置配额；
                            # count 用尽而 rem 未尽且队非空：状态保留续用
                            q = (q - 1) % 4
                            rem = weights[q]
                        wrr_state[port_name] = [q, rem]
            results.append(
                {"t": t, "port": port_name, "frames": frames,
                 "mirrors": mirrors}
            )
            continue
        _, t, port_name, src, dst, tag, ethertype, priority = item
        fid = frame_seq
        frame_seq += 1
        port_stats[port_name]["rx"] += 1
        if tag is None:
            vlan = by_name[port_name]["pvid"]
            rejected = False
        else:
            vlan = tag
            ingress = by_name[port_name]
            rejected = (
                ingress["mode"] == "access" or vlan not in ingress["allowed"]
            )
        if rejected:  # VLAN 准入拒绝：不学习、不计 VLAN
            port_stats[port_name]["drop"] += 1
            results.append(
                {"t": t, "action": "drop", "ports": [], "dropped": [],
                 "mirrors": []}
            )
            continue
        # VLAN 准入后：以有效 VLAN 及原字段做 ACL 匹配（每帧仅一次）
        acl_action, to_vlan = acl_match(vlan, src, dst, ethertype, priority)
        if acl_action == "remark":
            if to_vlan in by_name[port_name]["allowed"]:
                vlan = to_vlan  # 新 VLAN 用于后续全部处理
            else:  # remark 目标不在入端口 allowed：按 drop 处理
                acl_action = "drop"
        if acl_action == "drop":  # 不学习、不计风暴、不镜像、不发送
            port_stats[port_name]["drop"] += 1
            vlan_stats[vlan]["rx"] += 1
            vlan_stats[vlan]["drop"] += 1
            results.append(
                {"t": t, "action": "drop", "ports": [], "dropped": [],
                 "mirrors": []}
            )
            continue
        # 入端口命中 sources 则复制；remark 后副本携带新 VLAN（镜像不入队）
        ingress_copy = None
        if direction in ("ingress", "both") and port_name in source_set:
            copy_tag = vlan if acl_action == "remark" else tag
            ingress_copy = mirror_entry("ingress", copy_tag, port_name, t)
        vlan_stats[vlan]["rx"] += 1
        ingress_lag = lag_of.get(port_name)
        if ingress_lag is not None:
            usable = member_available(port_name, t, vlan)
            state = "forwarding" if usable else None
        else:
            usable = True
            _, state = port_status(port_name, t)
        egress = []
        action = "drop"
        if usable:  # 不可用成员入帧丢弃且不学习
            learn_port = ingress_lag["name"] if ingress_lag else port_name
            suppressed = suppress(
                t, port_name, vlan, src, dst, state, learn_port
            )
            if not suppressed and state == "forwarding":
                is_group = int(dst[:2], 16) & 1
                hit = None if is_group else fdb.get((vlan, dst))
                if hit is not None and hit[0] != learn_port:
                    target = hit[0]
                    target_lag = lag_by_name.get(target)
                    if target_lag is not None:
                        candidates = lag_candidates(target_lag, t, vlan)
                        if candidates:  # 无候选按无出口丢弃
                            egress = [
                                lag_pick(target_lag, candidates, src, dst, vlan)
                            ]
                            action = "unicast"
                    else:
                        target_up, target_state = port_status(target, t)
                        if (
                            target_up
                            and target_state == "forwarding"
                            and vlan in by_name[target]["allowed"]
                        ):
                            egress = [target]
                            action = "unicast"
                elif hit is None:
                    selected = {}  # lag 名 -> 本帧选中的成员
                    for lag in lags:
                        if ingress_lag is not None and lag is ingress_lag:
                            continue  # 禁止组内回送
                        candidates = lag_candidates(lag, t, vlan)
                        if candidates:
                            selected[lag["name"]] = lag_pick(
                                lag, candidates, src, dst, vlan
                            )
                    for port in ports:
                        name = port["name"]
                        lag = lag_of.get(name)
                        if lag is not None:
                            if selected.get(lag["name"]) == name:
                                egress.append(name)
                        elif (
                            vlan in port["allowed"]
                            and name != port_name
                            and port_status(name, t) == (True, "forwarding")
                        ):
                            egress.append(name)
                    if egress:
                        action = "flood"
        out_ports = []
        dropped = []
        queue_idx = qos_map[priority]
        for name in egress:  # 按 egress 序逐口入队；镜像不随之产生
            out_tag = None if vlan in by_name[name]["untagged"] else vlan
            if admit(name, queue_idx):
                egress_queues[name][queue_idx].append(
                    {"id": fid, "vlan": vlan, "mirror": out_tag}
                )
                out_ports.append({"name": name, "vlan": out_tag})
            else:  # 拒绝：计出口与 VLAN drop，不入队
                port_stats[name]["drop"] += 1
                vlan_stats[vlan]["drop"] += 1
                dropped.append(name)
        if not egress:  # 无出口：沿用 acl，计入口与 VLAN drop
            port_stats[port_name]["drop"] += 1
            vlan_stats[vlan]["drop"] += 1
        results.append(
            {"t": t, "action": action, "ports": out_ports,
             "dropped": dropped,
             "mirrors": [ingress_copy] if ingress_copy is not None else []}
        )
    return {
        "results": results,
        "ports": [
            {
                "name": port["name"],
                "rx": port_stats[port["name"]]["rx"],
                "tx": port_stats[port["name"]]["tx"],
                "drop": port_stats[port["name"]]["drop"],
            }
            for port in ports
        ],
        "vlans": [
            {
                "vlan": vlan,
                "rx": vlan_stats[vlan]["rx"],
                "tx": vlan_stats[vlan]["tx"],
                "drop": vlan_stats[vlan]["drop"],
            }
            for vlan in sorted(vlan_stats)
        ],
    }


def qos_check_work(
    bridges, links, delay, bridge_name, ports, age, storm, lags, acl, qos,
    max_frame, events, limit
):
    """qos-check 的工作量预演：独立链路副本与空状态，无副作用。

    计费与 qos 完全一致；坏帧不改变 FDB、风暴/迁移队列与出口队列，仍按帧
    计入每帧开销。累计等于上限合法，首次超过即抛 QosWorkLimit。
    """
    window = storm["window"]
    limits = storm["limits"]
    move_limit = storm["move_limit"]
    hold = storm["hold"]
    qos_map = qos["map"]
    cap = qos["cap"]
    sched_mode = qos["mode"]
    weights = qos["weights"]
    drop_mode = qos["drop"]
    weight_total = sum(weights)
    quotas = [-(-(cap * w) // weight_total) for w in weights]  # 上取整
    B = len(bridges)
    L = len(links)
    P = len(ports)
    R = len(acl)
    sim_links = [dict(link) for link in links]
    by_id = {link["id"]: link for link in sim_links}
    by_name = {port["name"]: port for port in ports}
    lag_by_name = {lag["name"]: lag for lag in lags}
    lag_of = {}  # 成员物理口 -> lag
    member_up = {}  # 成员物理口 -> 动态可用（初始可用）
    for lag in lags:
        for member in lag["members"]:
            lag_of[member] = lag
            member_up[member] = True
    M = len(member_up)
    port_link = {}  # 本桥桥链路口名 -> link
    for link in sim_links:
        for end_bridge, end_port in (link["x"], link["y"]):
            if end_bridge == bridge_name:
                port_link[end_port] = link
    fdb = {}  # (vlan, mac) -> [逻辑口（物理口名或 lag 名）, seen]
    rate_queues = {}  # (入端口, vlan, 类别) -> 放行时刻 deque
    move_queues = {}  # (vlan, src) -> 迁移时刻 deque
    last_learn = {}  # (vlan, src) -> 最后学习逻辑口
    blocked = {}  # (入端口, vlan) -> 封锁截止时刻
    # 出口队列预演仅跟踪各端口 4 个优先级队列的长度
    egress_queues = {port["name"]: [0, 0, 0, 0] for port in ports}
    # 每物理出口持久 WRR 状态 (当前队, 剩余配额)；初始服务 3 队
    wrr_state = {port["name"]: [3, weights[3]] for port in ports}

def forward_security(
    bridges, links, delay, bridge_name, ports, age, storm, lags, mirror,
    acl, qos, security, events, observer=None
):
    window = storm["window"]
    limits = storm["limits"]
    move_limit = storm["move_limit"]
    hold = storm["hold"]
    sources = mirror["sources"]
    mirror_target = mirror["target"]
    direction = mirror["direction"]
    source_set = set(sources)
    qos_map = qos["map"]
    cap = qos["cap"]
    sched_mode = qos["mode"]
    weights = qos["weights"]
    drop_mode = qos["drop"]
    weight_total = sum(weights)
    quotas = [-(-(cap * w) // weight_total) for w in weights]  # 上取整
    sec_by_port = {entry["port"]: entry for entry in security}
    sec_order = [entry["port"] for entry in security]
    static_owner = {}  # (vlan, mac) -> 所属物理口
    for entry in security:
        for item in entry["static"]:
            static_owner[(item["vlan"], item["mac"])] = entry["port"]
    sec_down = set()  # 被 shutdown 永久禁用的物理口
    bound = {}  # (vlan, mac) -> 动态绑定的物理口（不老化、状态变化不清除）
    dynamic = {entry["port"]: set() for entry in security}  # 口 -> 动态绑定集
    violations = {entry["port"]: 0 for entry in security}
    if observer is not None:  # record：逐事件记录 applied 与新增输出
        observer["items"] = []
    by_id = {link["id"]: link for link in links}
    by_name = {port["name"]: port for port in ports}
    lag_by_name = {lag["name"]: lag for lag in lags}
    lag_of = {}  # 成员物理口 -> lag
    member_up = {}  # 成员物理口 -> 动态可用（初始可用）
    for lag in lags:
        for member in lag["members"]:
            lag_of[member] = lag
            member_up[member] = True
    port_link = {}  # 本桥桥链路口名 -> link
    for link in links:
        for end_bridge, end_port in (link["x"], link["y"]):
            if end_bridge == bridge_name:
                port_link[end_port] = link
    fdb = {}  # (vlan, mac) -> [逻辑口（物理口名或 lag 名）, seen]
    port_stats = {
        port["name"]: {"rx": 0, "tx": 0, "drop": 0} for port in ports
    }
    vlan_stats = {}
    for port in ports:
        for vlan in port["allowed"]:
            vlan_stats.setdefault(vlan, {"rx": 0, "tx": 0, "drop": 0})
    rate_queues = {}  # (入端口, vlan, 类别) -> 放行时刻 deque
    move_queues = {}  # (vlan, src) -> 迁移时刻 deque
    last_learn = {}  # (vlan, src) -> 最后学习逻辑口
    blocked = {}  # (入端口, vlan) -> 封锁截止时刻
    results = []
    # 出口队列：每端口 4 个优先级 FIFO，存 {"id","vlan","mirror"}
    egress_queues = {
        port["name"]: [deque(), deque(), deque(), deque()] for port in ports
    }
    # 每物理出口持久 WRR 状态 (当前队, 剩余配额)；初始服务 3 队
    wrr_state = {
        port["name"]: [3, weights[3]] for port in ports
    }
    frame_seq = 0  # 全局零基帧序号（仅帧事件占用）

    def converge(t):
        _, _, new_roles = stp_converge(bridges, links)
        for name in bridges:
            for port, role in new_roles[name].items():
                key = (name, port)
                if role in STP_TIMED_ROLES:
                    if previous.get(key) != role:  # 同角色不重计时
                        since[key] = t
                else:
                    since.pop(key, None)
        previous.clear()
        for name in bridges:
            for port, role in new_roles[name].items():
                previous[(name, port)] = role
        roles.clear()
        for name in bridges:
            roles[name] = new_roles[name]

    def forwarding_ports(t):
        result = set()
        for name, link in port_link.items():
            key = (bridge_name, name)
            role = roles[bridge_name][name]
            if (
                by_name[name]["up"]
                and name not in sec_down
                and link["up"]
                and role in STP_TIMED_ROLES
                and t - since[key] >= 2 * delay
            ):
                result.add(name)
        return result

    def port_status(name, t):
        """返回 (物理 up, STP 状态)；边缘口恒为 up 即 forwarding。"""
        if name in sec_down:  # shutdown：永久按 down 口处理
            return False, "down"
        port = by_name[name]
        link = port_link.get(name)
        if link is None:
            return port["up"], ("forwarding" if port["up"] else "down")
        if not port["up"]:
            return False, "down"
        if not link["up"]:
            return False, "disabled"
        role = roles[bridge_name][name]
        if role in STP_TIMED_ROLES:
            elapsed = t - since[(bridge_name, name)]
            if elapsed < delay:
                state = "discarding"
            elif elapsed < 2 * delay:
                state = "learning"
            else:
                state = "forwarding"
        else:
            state = "discarding"  # alternate
        return True, state

    def is_forwarding(name, t):
        """LAG 成员还需动态 up 才算 forwarding。"""
        phys_up, state = port_status(name, t)
        if not phys_up or state != "forwarding":
            return False
        return name not in member_up or member_up[name]

    def member_available(name, t, vlan):
        """成员可用：动态 up、端口 up、STP forwarding 且允许该 VLAN。"""
        port = by_name[name]
        if not member_up[name] or not port["up"] or vlan not in port["allowed"]:
            return False
        return port_status(name, t) == (True, "forwarding")

    def lag_candidates(lag, t, vlan):
        """可用候选成员，按 members 顺序。"""
        return [
            member
            for member in lag["members"]
            if member_available(member, t, vlan)
        ]

    def lag_pick(lag, candidates, src, dst, vlan):
        parts = []
        for field in lag["hash"]:
            if field == "src":
                parts.append(src)
            elif field == "dst":
                parts.append(dst)
            else:
                parts.append(str(vlan))
        digest = zlib.crc32("|".join(parts).encode("utf-8")) & 0xFFFFFFFF
        return candidates[digest % len(candidates)]

    def suppress(t, port_name, vlan, src, dst, state, learn_port):
        """风暴控制：返回 True 表示本帧被抑制（不学习、不发送）。"""
        if (port_name, vlan) in blocked:  # 封锁帧不检测
            return True
        if state not in ("learning", "forwarding"):
            return False
        is_group = int(dst[:2], 16) & 1
        if dst == BROADCAST_MAC:
            category = "broadcast"
        elif is_group:
            category = "multicast"
        else:
            category = None if fdb.get((vlan, dst)) else "unknown"
        if category is not None:
            queue = rate_queues.get((port_name, vlan, category))
            if queue is None:
                queue = deque(maxlen=limits[category])
                rate_queues[(port_name, vlan, category)] = queue
            while queue and t - queue[0] >= window:
                queue.popleft()
            if len(queue) >= limits[category]:  # 余量已达上限：丢弃
                return True
        prev = last_learn.get((vlan, src))
        if prev is not None and prev != learn_port:  # 学习端口迁移
            queue = move_queues.get((vlan, src))
            if queue is None:
                queue = deque(maxlen=move_limit)
                move_queues[(vlan, src)] = queue
            while queue and t - queue[0] >= window:
                queue.popleft()
            queue.append(t)
            if len(queue) >= move_limit:  # 迁移数达上限：封锁入端口/VLAN 并丢弃
                blocked[(port_name, vlan)] = t + hold
                return True
        if category is not None:  # 速率名额仅在帧实际放行时占用
            rate_queues[(port_name, vlan, category)].append(t)
        fdb[(vlan, src)] = [learn_port, t]
        last_learn[(vlan, src)] = learn_port
        return False

    def target_available(t):
        """镜像输出口须物理 up；其本桥链路（若有）也须 up。STP 不阻止镜像。"""
        if mirror_target in sec_down:
            return False
        port = by_name[mirror_target]
        if not port["up"]:
            return False
        link = port_link.get(mirror_target)
        if link is not None and not link["up"]:
            return False
        return True

    def mirror_entry(direction_name, tag, source, t):
        """构造镜像副本；tag 为源侧线路上实际携带的标签（可为 None）。"""
        if not target_available(t):  # 不可用则无副本
            return None
        port_stats[mirror_target]["tx"] += 1  # 副本只计 target 的 tx
        return {
            "name": mirror_target,
            "vlan": tag,
            "direction": direction_name,
            "source": source,
        }

    def acl_match(vlan, src, dst, ethertype, priority):
        """按数组序首条命中；未命中视为 allow。"""
        for rule in acl:
            if (
                (rule["src"] is None or rule["src"] == src)
                and (rule["dst"] is None or rule["dst"] == dst)
                and (rule["vlan"] is None or rule["vlan"] == vlan)
                and (
                    rule["ethertype"] is None
                    or rule["ethertype"] == ethertype
                )
                and (
                    rule["priority"] is None or rule["priority"] == priority
                )
            ):
                return rule["action"], rule["to_vlan"]
        return "allow", None

    def clear_queue(name):
        """非 forwarding 清队：逐帧计出口与 VLAN drop。"""
        for q in range(4):
            while egress_queues[name][q]:
                frame = egress_queues[name][q].popleft()
                port_stats[name]["drop"] += 1
                vlan_stats[frame["vlan"]]["drop"] += 1

    def admit(name, queue_idx):
        """tail：总数达 cap 即拒；weighted：任一队列配额满即拒。"""
        queues = egress_queues[name]
        if drop_mode == "tail":
            return sum(len(q) for q in queues) < cap
        return all(len(queues[q]) < quotas[q] for q in range(4))

    def security_check(port_name, vlan, src):
        """端口安全：返回 True 表示违例（丢本帧；shutdown 另永久禁口）。"""
        entry = sec_by_port[port_name]
        key = (vlan, src)
        owner = static_owner.get(key)
        if owner is not None:  # 静态源只准从所属口进入
            if owner == port_name:
                return False
        else:
            bound_port = bound.get(key)
            if bound_port == port_name:  # 重复源不增数
                return False
            if bound_port is None and len(dynamic[port_name]) < entry["limit"]:
                bound[key] = port_name  # 首次绑定入端口
                dynamic[port_name].add(key)
                return False
            # 已绑定别口，或本口动态数达到 limit
        violations[port_name] += 1
        if entry["action"] == "shutdown":
            sec_down.add(port_name)  # 永久按 down 口禁用
            for old in dynamic[port_name]:  # 清动态绑定
                del bound[old]
            dynamic[port_name].clear()
            clear_queue(port_name)  # 离开 forwarding：清队
        return True

    previous = {}  # (bridge, port) -> 上一轮角色
    since = {}  # (bridge, port) -> 获得当前 root/designated 角色的时刻
    roles = {name: {} for name in bridges}

    converge(0)
    for item in events:
        t = item[1]
        for key in [k for k, (_, seen) in fdb.items() if t - seen >= age]:
            del fdb[key]
        for key in [k for k, until in blocked.items() if t >= until]:
            del blocked[key]
        if item[0] == "link":
            _, t, lid, up = item
            link_changed = by_id[lid]["up"] != up
            if link_changed:  # 幂等链路事件不重算拓扑
                old_forwarding = forwarding_ports(t)
                by_id[lid]["up"] = up

                by_id[lid]["up"] = up
                converge(t)
                for name in old_forwarding - forwarding_ports(t):
                    for key in [k for k, (p, _) in fdb.items() if p == name]:
                        del fdb[key]
                    clear_queue(name)  # 离开 forwarding：清队
            if observer is not None:
                observer["items"].append(
                    {"kind": "link", "t": t, "applied": link_changed,
                     "output": None}
                )
            continue
        if item[0] == "member":
            _, t, member, up = item
            member_changed = member_up[member] != up
            member_up[member] = up  # 幂等无作用；可用性变化不清 FDB
            if not up:  # 成员下线即非 forwarding：清队
                clear_queue(member)
            if observer is not None:
                observer["items"].append(
                    {"kind": "member", "t": t, "applied": member_changed,
                     "output": None}
                )
            continue
        if item[0] == "service":
            _, t, port_name, count = item
            frames = []
            mirrors = []
            if not is_forwarding(port_name, t):  # 非 forwarding：清队不服务
                clear_queue(port_name)
            else:
                queues = egress_queues[port_name]
                served = 0

                def dequeue_one():
                    frame = queues[q].popleft()
                    port_stats[port_name]["tx"] += 1  # tx 仅服务时计
                    vlan_stats[frame["vlan"]]["tx"] += 1
                    frames.append(frame["id"])
                    # 仅实际产生出站副本才追加（无 null 占位），与发送帧同序
                    if (
                        direction in ("egress", "both")
                        and port_name in source_set
                    ):
                        copy = mirror_entry(
                            "egress", frame["mirror"], port_name, t
                        )
                        if copy is not None:
                            mirrors.append(copy)

                while served < count:
                    if sched_mode == "sp":
                        q = next(
                            (q for q in (3, 2, 1, 0) if queues[q]), None
                        )
                        if q is None:
                            break
                        dequeue_one()
                        served += 1
                    else:  # wrr：持久状态 (q, rem)
                        q, rem = wrr_state[port_name]
                        if not any(queues):  # 四队全空：停止且状态不变
                            break
                        while not queues[q]:  # 当前队空：推进并重置配额
                            q = (q - 1) % 4
                            rem = weights[q]
                        dequeue_one()
                        served += 1
                        rem -= 1  # 每发一帧 rem 减 1
                        if rem == 0 or not queues[q]:
                            # rem 用尽或当前队变空：推进并重置配额；
                            # count 用尽而 rem 未尽且队非空：状态保留续用
                            q = (q - 1) % 4
                            rem = weights[q]
                        wrr_state[port_name] = [q, rem]
            results.append(
                {"t": t, "port": port_name, "frames": frames,
                 "mirrors": mirrors}
            )
            if observer is not None:
                observer["items"].append(
                    {"kind": "service", "t": t, "applied": True,
                     "output": results[-1]}
                )
            continue
        if item[0] in ("reload", "rollback"):
            _, t, new_age, new_acl, new_security, changes = item
            new_by_port = {entry["port"]: entry for entry in new_security}
            new_static_owner = {}
            for entry in new_security:
                for static in entry["static"]:
                    new_static_owner[(static["vlan"], static["mac"])] = (
                        entry["port"]
                    )
            # 动态绑定数超新 limit 或动态 (vlan, mac) 入新 static：整批无效
            for name, macs in dynamic.items():
                if len(macs) > new_by_port[name]["limit"]:
                    raise InvalidInput("dynamic bindings exceed new limit")
            for key in bound:
                if key in new_static_owner:
                    raise InvalidInput("dynamic binding in new static")
            # 原子替换 age/acl/security；FDB、绑定、安全状态、队列、调度、
            # 风暴记录与计数全部保留，新规则自下一事件生效
            age = new_age
            acl = new_acl
            sec_by_port = new_by_port
            sec_order = [entry["port"] for entry in new_security]
            static_owner = new_static_owner
            results.append(
                {"t": t, "action": item[0], "changes": changes}
            )
            if observer is not None:
                observer["items"].append(
                    {"kind": item[0], "t": t, "applied": True,
                     "output": results[-1]}
                )
            continue
        _, t, port_name, src, dst, tag, ethertype, priority = item
        fid = frame_seq
        frame_seq += 1
        port_stats[port_name]["rx"] += 1
        if tag is None:
            vlan = by_name[port_name]["pvid"]
            rejected = False
        else:
            vlan = tag
            ingress = by_name[port_name]
            rejected = (
                ingress["mode"] == "access" or vlan not in ingress["allowed"]
            )
        if rejected:  # VLAN 准入拒绝：不学习、不计 VLAN
            port_stats[port_name]["drop"] += 1
            results.append(
                {"t": t, "action": "drop", "ports": [], "dropped": [],
                 "mirrors": []}
            )
            if observer is not None:
                observer["items"].append(
                    {"kind": "frame", "t": t, "applied": True,
                     "output": results[-1]}
                )
            continue
        # VLAN 准入后：以有效 VLAN 及原字段做 ACL 匹配（每帧仅一次）
        acl_action, to_vlan = acl_match(vlan, src, dst, ethertype, priority)
        if acl_action == "remark":
            if to_vlan in by_name[port_name]["allowed"]:
                vlan = to_vlan  # 新 VLAN 用于后续全部处理
            else:  # remark 目标不在入端口 allowed：按 drop 处理
                acl_action = "drop"
        if acl_action == "drop":  # 不学习、不计风暴、不镜像、不发送
            port_stats[port_name]["drop"] += 1
            vlan_stats[vlan]["rx"] += 1
            vlan_stats[vlan]["drop"] += 1
            results.append(
                {"t": t, "action": "drop", "ports": [], "dropped": [],
                 "mirrors": []}
            )
            if observer is not None:
                observer["items"].append(
                    {"kind": "frame", "t": t, "applied": True,
                     "output": results[-1]}
                )
            continue
        ingress_lag = lag_of.get(port_name)
        if ingress_lag is not None:
            usable = member_available(port_name, t, vlan)
            state = "forwarding" if usable else None
        else:
            usable = True
            _, state = port_status(port_name, t)
        # 可学习帧在 FDB 前做端口安全检查；违例不学习、不计风暴、不镜像
        if (
            usable
            and state in ("learning", "forwarding")
            and security_check(port_name, vlan, src)
        ):
            port_stats[port_name]["drop"] += 1
            vlan_stats[vlan]["rx"] += 1
            vlan_stats[vlan]["drop"] += 1
            results.append(
                {"t": t, "action": "drop", "ports": [], "dropped": [],
                 "mirrors": []}
            )
            if observer is not None:
                observer["items"].append(
                    {"kind": "frame", "t": t, "applied": True,
                     "output": results[-1]}
                )
            continue
        # 入端口命中 sources 则复制；remark 后副本携带新 VLAN（镜像不入队）
        ingress_copy = None
        if direction in ("ingress", "both") and port_name in source_set:
            copy_tag = vlan if acl_action == "remark" else tag
            ingress_copy = mirror_entry("ingress", copy_tag, port_name, t)
        vlan_stats[vlan]["rx"] += 1
        egress = []
        action = "drop"
        if usable:  # 不可用成员入帧丢弃且不学习
            learn_port = ingress_lag["name"] if ingress_lag else port_name
            suppressed = suppress(
                t, port_name, vlan, src, dst, state, learn_port
            )
            if not suppressed and state == "forwarding":
                is_group = int(dst[:2], 16) & 1
                hit = None if is_group else fdb.get((vlan, dst))
                if hit is not None and hit[0] != learn_port:
                    target = hit[0]
                    target_lag = lag_by_name.get(target)
                    if target_lag is not None:
                        candidates = lag_candidates(target_lag, t, vlan)
                        if candidates:  # 无候选按无出口丢弃
                            egress = [
                                lag_pick(target_lag, candidates, src, dst, vlan)
                            ]
                            action = "unicast"
                    else:
                        target_up, target_state = port_status(target, t)
                        if (
                            target_up
                            and target_state == "forwarding"
                            and vlan in by_name[target]["allowed"]
                        ):
                            egress = [target]
                            action = "unicast"
                elif hit is None:
                    selected = {}  # lag 名 -> 本帧选中的成员
                    for lag in lags:
                        if ingress_lag is not None and lag is ingress_lag:
                            continue  # 禁止组内回送
                        candidates = lag_candidates(lag, t, vlan)
                        if candidates:
                            selected[lag["name"]] = lag_pick(
                                lag, candidates, src, dst, vlan
                            )
                    for port in ports:
                        name = port["name"]
                        lag = lag_of.get(name)
                        if lag is not None:
                            if selected.get(lag["name"]) == name:
                                egress.append(name)
                        elif (
                            vlan in port["allowed"]
                            and name != port_name
                            and port_status(name, t) == (True, "forwarding")
                        ):
                            egress.append(name)
                    if egress:
                        action = "flood"
        out_ports = []
        dropped = []
        queue_idx = qos_map[priority]
        for name in egress:  # 按 egress 序逐口入队；镜像不随之产生
            out_tag = None if vlan in by_name[name]["untagged"] else vlan
            if admit(name, queue_idx):
                egress_queues[name][queue_idx].append(
                    {"id": fid, "vlan": vlan, "mirror": out_tag}
                )
                out_ports.append({"name": name, "vlan": out_tag})
            else:  # 拒绝：计出口与 VLAN drop，不入队
                port_stats[name]["drop"] += 1
                vlan_stats[vlan]["drop"] += 1
                dropped.append(name)
        if not egress:  # 无出口：沿用 acl，计入口与 VLAN drop
            port_stats[port_name]["drop"] += 1
            vlan_stats[vlan]["drop"] += 1
        results.append(
            {"t": t, "action": action, "ports": out_ports,
             "dropped": dropped,
             "mirrors": [ingress_copy] if ingress_copy is not None else []}
        )
        if observer is not None:
            observer["items"].append(
                {"kind": "frame", "t": t, "applied": True,
                 "output": results[-1]}
            )
    return {
        "results": results,
        "ports": [
            {
                "name": port["name"],
                "rx": port_stats[port["name"]]["rx"],
                "tx": port_stats[port["name"]]["tx"],
                "drop": port_stats[port["name"]]["drop"],
            }
            for port in ports
        ],
        "vlans": [
            {
                "vlan": vlan,
                "rx": vlan_stats[vlan]["rx"],
                "tx": vlan_stats[vlan]["tx"],
                "drop": vlan_stats[vlan]["drop"],
            }
            for vlan in sorted(vlan_stats)
        ],
        "security": [
            {
                "port": name,
                "learned": [
                    {"vlan": vlan, "mac": mac}
                    for vlan, mac in sorted(dynamic[name])
                ],
                "violations": violations[name],
                "shutdown": name in sec_down,
            }
            for name in sec_order
        ],
    }


def forward_security_check(
    bridges, links, delay, bridge_name, ports, age, storm, lags, mirror,
    acl, qos, security, max_frame, events
):
    window = storm["window"]
    limits = storm["limits"]
    move_limit = storm["move_limit"]
    hold = storm["hold"]
    sources = mirror["sources"]
    mirror_target = mirror["target"]

def reload_work(
    bridges, links, delay, bridge_name, ports, age, storm, lags, acl, qos,
    security, events, limit
):
    """reload 的工作量预演：独立链路副本与空状态，无副作用。

    B、L、P、M、R 为桥、链路、物理端口、聚合成员、当前 ACL 规则数，U 为
    up 链路数；累计值初始 B+L+2U。各事件在按 t 老化 FDB 与解封前取
    X=FDB 项数+封锁项数+速率与迁移队列时间戳总数，D=动态绑定数，
    N=全部出口排队帧数，S=所指端口排队帧数（帧取入端口）：帧计
    X+3P+M+R+D+S+1；链路先应用 up，改变以新 U 计 X+N+B+L+2U+2P+1，
    幂等计 X+1；成员 down 计 X+S+1、up 计 X+1；服务计 X+S+1；重载令
    A/T 为新 ACL 规则数/新静态绑定数，计 X+D+P+A+T+1，再采用新
    age/ACL/security。再按既有队列、调度、清队与安全规则处理并更新
    预演状态。累计等于上限合法，首次超过即抛 ReloadWorkLimit。
    """
    window = storm["window"]
    limits = storm["limits"]
    move_limit = storm["move_limit"]
    hold = storm["hold"]
    qos_map = qos["map"]
    cap = qos["cap"]
    sched_mode = qos["mode"]
    weights = qos["weights"]
    drop_mode = qos["drop"]
    weight_total = sum(weights)
    quotas = [-(-(cap * w) // weight_total) for w in weights]  # 上取整
    sec_by_port = {entry["port"]: entry for entry in security}
    static_owner = {}  # (vlan, mac) -> 所属物理口
    for entry in security:
        for item in entry["static"]:
            static_owner[(item["vlan"], item["mac"])] = entry["port"]
    sec_down = set()  # 被 shutdown 永久禁用的物理口
    bound = {}  # (vlan, mac) -> 动态绑定的物理口
    dynamic = {entry["port"]: set() for entry in security}  # 口 -> 动态绑定集
    B = len(bridges)
    L = len(links)
    P = len(ports)
    R = len(acl)
    sim_links = [dict(link) for link in links]
    by_id = {link["id"]: link for link in sim_links}
    by_name = {port["name"]: port for port in ports}
    lag_by_name = {lag["name"]: lag for lag in lags}
    lag_of = {}  # 成员物理口 -> lag
    member_up = {}  # 成员物理口 -> 动态可用（初始可用）
    for lag in lags:
        for member in lag["members"]:
            lag_of[member] = lag
            member_up[member] = True
    M = len(member_up)
    port_link = {}  # 本桥桥链路口名 -> link
    for link in sim_links:
        for end_bridge, end_port in (link["x"], link["y"]):
            if end_bridge == bridge_name:
                port_link[end_port] = link
    fdb = {}  # (vlan, mac) -> [逻辑口（物理口名或 lag 名）, seen]
    rate_queues = {}  # (入端口, vlan, 类别) -> 放行时刻 deque
    move_queues = {}  # (vlan, src) -> 迁移时刻 deque
    last_learn = {}  # (vlan, src) -> 最后学习逻辑口
    blocked = {}  # (入端口, vlan) -> 封锁截止时刻
    # 出口队列预演仅跟踪各端口 4 个优先级队列的长度
    egress_queues = {port["name"]: [0, 0, 0, 0] for port in ports}
    # 每物理出口持久 WRR 状态 (当前队, 剩余配额)；初始服务 3 队
    wrr_state = {port["name"]: [3, weights[3]] for port in ports}

    previous = {}  # (bridge, port) -> 上一轮角色
    since = {}  # (bridge, port) -> 获得当前 root/designated 角色的时刻
    roles = {name: {} for name in bridges}

    def converge(t):
        _, _, new_roles = stp_converge(bridges, sim_links)
        for name in bridges:
            for port, role in new_roles[name].items():
                key = (name, port)
                if role in STP_TIMED_ROLES:
                    if previous.get(key) != role:  # 同角色不重计时
                        since[key] = t
                else:
                    since.pop(key, None)
        previous.clear()
        for name in bridges:
            for port, role in new_roles[name].items():
                previous[(name, port)] = role
        roles.clear()
        for name in bridges:
            roles[name] = new_roles[name]

    def forwarding_ports(t):
        result = set()
        for name, link in port_link.items():
            key = (bridge_name, name)
            role = roles[bridge_name][name]
            if (
                by_name[name]["up"]
                and name not in sec_down
                and link["up"]
                and role in STP_TIMED_ROLES
                and t - since[key] >= 2 * delay
            ):
                result.add(name)
        return result

    def port_status(name, t):
        """返回 (物理 up, STP 状态)；边缘口恒为 up 即 forwarding。"""
        if name in sec_down:  # shutdown：永久按 down 口处理
            return False, "down"
        port = by_name[name]
        link = port_link.get(name)
        if link is None:
            return port["up"], ("forwarding" if port["up"] else "down")
        if not port["up"]:
            return False, "down"
        if not link["up"]:
            return False, "disabled"
        role = roles[bridge_name][name]
        if role in STP_TIMED_ROLES:
            elapsed = t - since[(bridge_name, name)]
            if elapsed < delay:
                state = "discarding"
            elif elapsed < 2 * delay:
                state = "learning"
            else:
                state = "forwarding"
        else:
            state = "discarding"  # alternate
        return True, state

    def is_forwarding(name, t):
        """LAG 成员还需动态 up 才算 forwarding。"""
        phys_up, state = port_status(name, t)
        if not phys_up or state != "forwarding":
            return False
        return name not in member_up or member_up[name]

    def member_available(name, t, vlan):
        """成员可用：动态 up、端口 up、STP forwarding 且允许该 VLAN。"""
        port = by_name[name]
        if not member_up[name] or not port["up"] or vlan not in port["allowed"]:
            return False
        return port_status(name, t) == (True, "forwarding")

    def lag_candidates(lag, t, vlan):
        """可用候选成员，按 members 顺序。"""
        return [
            member
            for member in lag["members"]
            if member_available(member, t, vlan)
        ]

    def lag_pick(lag, candidates, src, dst, vlan):
        parts = []
        for field in lag["hash"]:
            if field == "src":
                parts.append(src)
            elif field == "dst":
                parts.append(dst)
            else:
                parts.append(str(vlan))
        digest = zlib.crc32("|".join(parts).encode("utf-8")) & 0xFFFFFFFF
        return candidates[digest % len(candidates)]

    def suppress(t, port_name, vlan, src, dst, state, learn_port):
        """风暴控制：返回 True 表示本帧被抑制（不学习、不发送）。"""
        if (port_name, vlan) in blocked:  # 封锁帧不检测
            return True
        if state not in ("learning", "forwarding"):
            return False
        is_group = int(dst[:2], 16) & 1
        if dst == BROADCAST_MAC:
            category = "broadcast"
        elif is_group:
            category = "multicast"
        else:
            category = None if fdb.get((vlan, dst)) else "unknown"
        if category is not None:
            queue = rate_queues.get((port_name, vlan, category))
            if queue is None:
                queue = deque(maxlen=limits[category])
                rate_queues[(port_name, vlan, category)] = queue
            while queue and t - queue[0] >= window:
                queue.popleft()
            if len(queue) >= limits[category]:  # 余量已达上限：丢弃
                return True
        prev = last_learn.get((vlan, src))
        if prev is not None and prev != learn_port:  # 学习端口迁移
            queue = move_queues.get((vlan, src))
            if queue is None:
                queue = deque(maxlen=move_limit)
                move_queues[(vlan, src)] = queue
            while queue and t - queue[0] >= window:
                queue.popleft()
            queue.append(t)
            if len(queue) >= move_limit:  # 迁移数达上限：封锁入端口/VLAN 并丢弃
                blocked[(port_name, vlan)] = t + hold
                return True
        if category is not None:  # 速率名额仅在帧实际放行时占用
            rate_queues[(port_name, vlan, category)].append(t)
        fdb[(vlan, src)] = [learn_port, t]
        last_learn[(vlan, src)] = learn_port
        return False

    def acl_match(vlan, src, dst, ethertype, priority):
        """按数组序首条命中；未命中视为 allow。"""
        for rule in acl:
            if (
                (rule["src"] is None or rule["src"] == src)
                and (rule["dst"] is None or rule["dst"] == dst)
                and (rule["vlan"] is None or rule["vlan"] == vlan)
                and (
                    rule["ethertype"] is None
                    or rule["ethertype"] == ethertype
                )
                and (
                    rule["priority"] is None
                    or rule["priority"] == priority
                )
            ):
                return rule["action"], rule["to_vlan"]
        return "allow", None

    def admit(name, queue_idx):
        """tail：总数达 cap 即拒；weighted：任一队列配额满即拒。"""
        counts = egress_queues[name]
        if drop_mode == "tail":
            return sum(counts) < cap
        return all(counts[q] < quotas[q] for q in range(4))

    def security_check(port_name, vlan, src):
        """端口安全：返回 True 表示违例（shutdown 另永久禁口并清队）。"""
        entry = sec_by_port[port_name]
        key = (vlan, src)
        owner = static_owner.get(key)
        if owner is not None:  # 静态源只准从所属口进入
            if owner == port_name:
                return False
        else:
            bound_port = bound.get(key)
            if bound_port == port_name:  # 重复源不增数
                return False
            if bound_port is None and len(dynamic[port_name]) < entry["limit"]:
                bound[key] = port_name  # 首次绑定入端口
                dynamic[port_name].add(key)
                return False
            # 已绑定别口，或本口动态数达到 limit
        if entry["action"] == "shutdown":
            sec_down.add(port_name)  # 永久按 down 口禁用
            for old in dynamic[port_name]:  # 清动态绑定
                del bound[old]
            dynamic[port_name].clear()
            egress_queues[port_name] = [0, 0, 0, 0]  # 离开 forwarding：清队
        return True

    U = sum(1 for link in sim_links if link["up"])
    work = B + L + 2 * U  # 初始收敛
    if work > limit:
        raise ReloadWorkLimit
    converge(0)
    for item in events:
        t = item[1]
        # 老化与解封前取 X、D（N、S 按需同点取）
        X = (
            len(fdb)
            + len(blocked)
            + sum(len(queue) for queue in rate_queues.values())
            + sum(len(queue) for queue in move_queues.values())
        )
        D = len(bound)
        kind = item[0]
        if kind == "link":
            up = item[3]
            changed = by_id[item[2]]["up"] != up
            if changed:  # 先应用 up，再以新 U 计
                U += 1 if up else -1
                N = sum(sum(counts) for counts in egress_queues.values())
                work += X + N + (B + L + 2 * U) + 2 * P + 1
            else:
                work += X + 1
        elif kind == "member":
            if item[3]:
                work += X + 1
            else:
                work += X + sum(egress_queues[item[2]]) + 1
        elif kind == "service":
            work += X + sum(egress_queues[item[2]]) + 1
        elif kind in ("reload", "rollback"):
            # 动态绑定数超新 limit 或动态 (vlan, mac) 入新 static 的整批无效
            # 判定先于工作量累加与超限判断：record/replay 按 invalid_input
            # 退出 4，且绝不触碰 LOG；rollback 按 reload 分支计费，
            # A/T 取恢复配置的 ACL 规则数/静态绑定数
            reload_by_port = {entry["port"]: entry for entry in item[4]}
            reload_static_owner = {}
            for entry in item[4]:
                for static in entry["static"]:
                    reload_static_owner[(static["vlan"], static["mac"])] = (
                        entry["port"]
                    )
            for name, macs in dynamic.items():
                if len(macs) > reload_by_port[name]["limit"]:
                    raise InvalidInput("dynamic bindings exceed new limit")
            for key in bound:
                if key in reload_static_owner:
                    raise InvalidInput("dynamic binding in new static")
            # A/T 为新 ACL 规则数/新静态绑定数
            work += (
                X
                + D
                + P
                + len(item[3])
                + sum(len(entry["static"]) for entry in item[4])
                + 1
            )
        else:  # 帧：S 取入端口排队帧数
            work += X + 3 * P + M + R + D + sum(egress_queues[item[2]]) + 1
        if work > limit:
            raise ReloadWorkLimit
        # 以下按既有规则处理并更新预演状态
        for key in [k for k, (_, seen) in fdb.items() if t - seen >= age]:
            del fdb[key]
        for key in [k for k, until in blocked.items() if t >= until]:
            del blocked[key]
        if kind == "link":
            if changed:  # 幂等链路事件不重算拓扑
                old_forwarding = forwarding_ports(t)
                by_id[item[2]]["up"] = item[3]
                converge(t)
                for name in old_forwarding - forwarding_ports(t):
                    for key in [k for k, (p, _) in fdb.items() if p == name]:
                        del fdb[key]
                    egress_queues[name] = [0, 0, 0, 0]  # 离开 forwarding：清队
            continue
        if kind == "member":
            member_up[item[2]] = item[3]  # 幂等无作用；可用性变化不清 FDB
            if not item[3]:  # 成员下线即非 forwarding：清队
                egress_queues[item[2]] = [0, 0, 0, 0]
            continue
        if kind == "service":
            _, _, port_name, count = item
            counts = egress_queues[port_name]
            if not is_forwarding(port_name, t):  # 非 forwarding：清队不服务
                egress_queues[port_name] = [0, 0, 0, 0]
            elif sched_mode == "sp":
                served = 0
                while served < count:
                    q = next((q for q in (3, 2, 1, 0) if counts[q]), None)
                    if q is None:
                        break
                    counts[q] -= 1
                    served += 1
            else:  # wrr：持久状态 (q, rem)
                served = 0
                while served < count:
                    q, rem = wrr_state[port_name]
                    if not any(counts):  # 四队全空：停止且状态不变
                        break
                    while not counts[q]:  # 当前队空：推进并重置配额
                        q = (q - 1) % 4
                        rem = weights[q]
                    counts[q] -= 1
                    served += 1
                    rem -= 1  # 每发一帧 rem 减 1
                    if rem == 0 or not counts[q]:
                        # rem 用尽或当前队变空：推进并重置配额；
                        # count 用尽而 rem 未尽且队非空：状态保留续用
                        q = (q - 1) % 4
                        rem = weights[q]
                    wrr_state[port_name] = [q, rem]
            continue
        if kind in ("reload", "rollback"):
            _, _, new_age, new_acl, new_security, _ = item
            new_by_port = {entry["port"]: entry for entry in new_security}
            new_static_owner = {}
            for entry in new_security:
                for static in entry["static"]:
                    new_static_owner[(static["vlan"], static["mac"])] = (
                        entry["port"]
                    )
            # 原子替换 age/acl/security；FDB、绑定、安全状态、队列、调度、
            # 风暴记录全部保留，新规则自下一事件生效
            age = new_age
            acl = new_acl
            R = len(new_acl)
            sec_by_port = new_by_port
            static_owner = new_static_owner
            continue
        _, _, port_name, src, dst, tag, ethertype, priority = item
        if tag is None:
            vlan = by_name[port_name]["pvid"]
            rejected = False
        else:
            vlan = tag
            ingress = by_name[port_name]
            rejected = (
                ingress["mode"] == "access" or vlan not in ingress["allowed"]
            )
        if rejected:  # VLAN 准入拒绝：不学习
            continue
        # VLAN 准入后：以有效 VLAN 及原字段做 ACL 匹配（每帧仅一次）
        acl_action, to_vlan = acl_match(vlan, src, dst, ethertype, priority)
        if acl_action == "remark":
            if to_vlan in by_name[port_name]["allowed"]:
                vlan = to_vlan  # 新 VLAN 用于后续全部处理
            else:  # remark 目标不在入端口 allowed：按 drop 处理
                acl_action = "drop"
        if acl_action == "drop":  # 不学习、不计风暴
            continue
        ingress_lag = lag_of.get(port_name)
        if ingress_lag is not None:
            usable = member_available(port_name, t, vlan)
            state = "forwarding" if usable else None
        else:
            usable = True
            _, state = port_status(port_name, t)
        # 可学习帧在 FDB 前做端口安全检查；违例不学习、不计风暴
        if (
            usable
            and state in ("learning", "forwarding")
            and security_check(port_name, vlan, src)
        ):
            continue
        egress = []
        if usable:  # 不可用成员入帧丢弃且不学习
            learn_port = ingress_lag["name"] if ingress_lag else port_name
            suppressed = suppress(
                t, port_name, vlan, src, dst, state, learn_port
            )
            if not suppressed and state == "forwarding":
                is_group = int(dst[:2], 16) & 1
                hit = None if is_group else fdb.get((vlan, dst))
                if hit is not None and hit[0] != learn_port:
                    target = hit[0]
                    target_lag = lag_by_name.get(target)
                    if target_lag is not None:
                        candidates = lag_candidates(target_lag, t, vlan)
                        if candidates:  # 无候选按无出口丢弃
                            egress = [
                                lag_pick(target_lag, candidates, src, dst, vlan)
                            ]
                    else:
                        target_up, target_state = port_status(target, t)
                        if (
                            target_up
                            and target_state == "forwarding"
                            and vlan in by_name[target]["allowed"]
                        ):
                            egress = [target]
                elif hit is None:
                    selected = {}  # lag 名 -> 本帧选中的成员
                    for lag in lags:
                        if ingress_lag is not None and lag is ingress_lag:
                            continue  # 禁止组内回送
                        candidates = lag_candidates(lag, t, vlan)
                        if candidates:
                            selected[lag["name"]] = lag_pick(
                                lag, candidates, src, dst, vlan
                            )
                    for port in ports:
                        name = port["name"]
                        lag = lag_of.get(name)
                        if lag is not None:
                            if selected.get(lag["name"]) == name:
                                egress.append(name)
                        elif (
                            vlan in port["allowed"]
                            and name != port_name
                            and port_status(name, t) == (True, "forwarding")
                        ):
                            egress.append(name)
        queue_idx = qos_map[priority]
        for name in egress:  # 按 egress 序逐口入队；镜像不随之产生
            if admit(name, queue_idx):
                egress_queues[name][queue_idx] += 1


def forward_security(
    bridges, links, delay, bridge_name, ports, age, storm, lags, mirror,
    acl, qos, security, events, observer=None
):
    window = storm["window"]
    limits = storm["limits"]
    move_limit = storm["move_limit"]

        # 状态语义校验后先按 record 同一公式无副作用预演；首次超限即停止，
        # 不正式重放，LOG 保持不动
        result, observer = _run_reload(config, events, True, max_replay_work)
        _verify_records(log, events, observer["items"])
        # 重放重建的 LOG 须与原文件逐字节一致（含 sha256 与 LF）
        rebuilt = _build_log_doc(config, events, observer["items"])
        if _log_bytes(rebuilt) != log_raw:
            raise InvalidInput("bad log")
        # 输出上界在全部日志语义与重放核对成功后判定；LOG 保持不动
        output = _result_bytes(result)
        if len(output) > max_output_bytes:
            _fail("output_limit")
            return 5
    except InvalidInput:
        _fail("invalid_input")
        return 4
    except ReloadWorkLimit:
        _fail("replay_work_limit")
        return 5
    sys.stdout.buffer.write(output)
    return 0


CONFIG_DIFF_MAX_INPUT_BYTES = 1024 * 1024


def _json_pointer_token(token):
    """RFC6901 reference token 转义：~ 编码为 ~0，/ 编码为 ~1。"""
    return token.replace("~", "~0").replace("/", "~1")


def _diff_collect(old, new, path, changes):
    """按键序无关契约收集 OLD、NEW 的差异项到 changes。

    对象递归，键按 Unicode 码点升序深度优先；数组整体比较且顺序敏感，
    整组不同仅出一项；标量按 JSON 类型与值比较。path 为 RFC6901 JSON
    Pointer（根为 ""）。仅不同的数组或标量（及缺失对象键）生成项。
    """
    if isinstance(old, dict) and isinstance(new, dict):
        for key in sorted(set(old) | set(new)):
            child = path + "/" + _json_pointer_token(key)
            if key in old and key in new:
                _diff_collect(old[key], new[key], child, changes)
            elif key in old:
                # 仅旧侧存在；合法 port-security 配置各层键集固定，不会到达
                changes.append(
                    {"path": child, "before": _canonical(old[key]),
                     "after": None}
                )
            else:
                changes.append(
                    {"path": child, "before": None,
                     "after": _canonical(new[key])}
                )
        return
    # 两数组整体（顺序敏感）、两标量（JSON 类型+值）或类别不一致：
    # 不同即整值一项，前后值按同一规则规范化
    if not _json_equal(old, new):
        changes.append(
            {"path": path, "before": _canonical(old),
             "after": _canonical(new)}
        )


def _diff_size(value):
    """工作量公式的 S：标量 1；数组 1+各元素 S 之和；
    对象 1+键数+各值 S 之和。"""
    if isinstance(value, dict):
        return 1 + len(value) + sum(_diff_size(item) for item in value.values())
    if isinstance(value, list):
        return 1 + sum(_diff_size(item) for item in value)
    return 1


def _diff_size_charge(value, remaining):
    """S 的计费版：从剩余额度扣减 S(value)，返回扣后额度（耗尽为 0）。

    对象先计 1+键数，再按键的 Unicode 码点升序逐值计费；数组先计 1，
    再按元素序逐项计费；标量计 1。累计首次超过剩余额度即抛
    DiffWorkLimit，不再访问后续元素或键值；额度足够时累计恰为
    S(value)，与 _diff_size 一致。
    """
    if isinstance(value, dict):
